sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    // clear existing choices in what needed field
    g_form.clearOptions('what_needed');

    // Define What Needed options based on Request Type
    var choices = [];

    switch (newValue) {
        case 'Human Resources':
            choices = ['Human Resources 1', 'Human Resources 2', 'Other'];
            break;
        case 'Facilities':
            choices = ['Facilities 1', 'Facilities 2', 'Other'];
            break;
        case 'Legal':
            choices = ['Legal 1', 'Legal 2', 'Other'];
            break;
        default:
            choices = ['Other']; 
    }

    choices.forEach(function(choice) {
        g_form.addOption('what_needed', choice, choice);
    });

    if (!g_form.isNewRecord() && oldValue) {
        g_form.setValue('what_needed', oldValue);
    }
}
